# Summarize actual outputs generated by steps 2 and 3.
args <- commandArgs(TRUE)
stopifnot(length(args)==1L,file.exists(args[1])); source(args[1])
write_tsv <- function(x,n) write.table(x,file.path(output_dir,n),sep="\t",row.names=FALSE,quote=FALSE,na="")
all_agreement<-list();all_retention<-list();all_composition<-list()
for(s in samples) {
 a<-read.delim(file.path(output_dir,paste0(s,"_agreement.tsv")),check.names=FALSE)
 a$sample<-s;all_agreement[[s]]<-a
 r<-read.delim(file.path(output_dir,paste0(s,"_retention.tsv")),check.names=FALSE)
 r$sample<-s;all_retention[[s]]<-r
 for(arm in c("org_mm","biomart")) {
  x<-read.delim(file.path(output_dir,paste0(s,"_",arm,"_labels.tsv")),check.names=FALSE)
  # Composition refers to primary assigned labels; doublets have a secondary label.
  valid<-!is.na(x$first_type)&nzchar(x$first_type)&!is.na(x$spot_class)&x$spot_class!="reject"
  tab<-as.data.frame(table(cell_type=as.character(x$first_type[valid])))
  names(tab)[2]<-"assigned_bins"
  tab$fraction_among_nonrejected<-tab$assigned_bins/sum(valid)
  tab$sample<-s;tab$mapping<-arm
  all_composition[[paste(s,arm)]]<-tab
 }
}
write_tsv(do.call(rbind,all_agreement),"all_samples_agreement.tsv")
write_tsv(do.call(rbind,all_retention),"all_samples_retention.tsv")
write_tsv(do.call(rbind,all_composition),"all_samples_primary_label_composition.tsv")
